import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import crypto from 'node:crypto';

const page = await (await fetch('http://127.0.0.1:9222/json/new?about:blank', { method: 'PUT' })).json();
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
let serial = 0;
const pending = new Map(), exceptions = [], failed = [];
ws.onmessage = ({ data }) => {
  const message = JSON.parse(data);
  if (message.method === 'Runtime.exceptionThrown') exceptions.push(message.params.exceptionDetails);
  if (message.method === 'Network.responseReceived' && message.params.response.status >= 400 && !message.params.response.url.endsWith('/favicon.ico')) failed.push(message.params.response.url);
  if (pending.has(message.id)) {
    const { resolve, reject } = pending.get(message.id); pending.delete(message.id);
    message.error ? reject(Error(JSON.stringify(message.error))) : resolve(message.result);
  }
};
/** Executa um comando no Chrome isolado, com timeout para não bloquear a sessão. */
function send(method, params = {}) {
  return new Promise((resolve, reject) => {
    const id = ++serial; const timer = setTimeout(() => { pending.delete(id); reject(Error('Tempo excedido: ' + method)); }, 25000);
    pending.set(id, { resolve: value => { clearTimeout(timer); resolve(value); }, reject: error => { clearTimeout(timer); reject(error); } });
    ws.send(JSON.stringify({ id, method, params }));
  });
}
/** Consulta a fixture ou o jogo local, devolvendo erros de execução explicitamente. */
async function evaluate(expression) {
  const response = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
  if (response.exceptionDetails) throw Error(JSON.stringify(response.exceptionDetails));
  return response.result.value;
}

try {
 await send('Runtime.enable');await send('Page.enable');await send('Network.enable');
 await send('Emulation.setDeviceMetricsOverride',{width:1280,height:800,deviceScaleFactor:1,mobile:false});
 await send('Page.navigate',{url:process.env.PILOT_REVIEW_URL+'/?debug=1'});
 for(let i=0;i<180;i++){if(await evaluate('Boolean(window.game?.startDebugPhase)'))break;await new Promise(r=>setTimeout(r,100));}
 await evaluate(`document.querySelector('#debug-phase-select').value='bear-chase';document.querySelector('#debug-phase-select').dispatchEvent(new Event('change',{bubbles:true}));`);
 let ready=false;for(let i=0;i<240;i++){const c=await evaluate('(()=>{const c=game.state.toyRoomInstance?.instance.chase;return {ready:c?.ready,error:c?.error};})()');if(c.error)throw Error(c.error);if(c.ready){ready=true;break;}await new Promise(r=>setTimeout(r,100));}assert.ok(ready);


 await evaluate('game.setPaused(true)');const rows=[],captures=[];
 for(const [width,height]of [[1280,800],[390,844],[844,390]]) {
 await send('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:width<900});await new Promise(r=>setTimeout(r,180));
 for(const difficulty of ['NORMAL','EASY'])for(const stage of ['RUNNING','FALLING','GAME_OVER']) {
 const row=await evaluate(`(async()=>{const c=game.state.toyRoomInstance.instance.chase,{createChaseState,stepChase}=await import('/src/js/bear-chase/ChaseSimulation.js'),{chaseMaxLives}=await import('/src/js/bear-chase/ChaseHealth.js'),T=await import('/src/vendor/three/three.module.js');c.difficulty='${difficulty}';c.state=createChaseState();Object.assign(c.state,{stage:'RUNNING',distance:20,age:20,time:20,gap:29,hits:chaseMaxLives(c.difficulty)-1,nextDrop:1000});if('${stage}'!=='RUNNING'){c.state.obstacles=[{id:1,x:0,z:20.05,age:1,width:1.15,kind:'blocks',fromX:0,fromZ:25}];stepChase(c.state,0,1/60,c.difficulty);for(let i=0;i<('${stage}'==='GAME_OVER'?70:30);i++)stepChase(c.state,1,1/60,c.difficulty);}const texts=[],ctx=c.ctx,original=ctx.fillText;ctx.fillText=function(text,...args){texts.push(text);return original.call(this,text,...args);};try{c.render();const first=c.canvas.toDataURL(),snap=c.snapshot();c.difficulty=c.difficulty==='EASY'?'NORMAL':'EASY';c.restore(snap);c.render();const box=new T.Box3().setFromObject(c.renderer.girl);return {stage:c.state.stage,difficulty:c.difficulty,hits:c.state.hits,texts,restored:c.difficulty==='${difficulty}',stable:first===c.canvas.toDataURL(),rotation:c.renderer.girl.rotation.x,visible:c.renderer.girl.visible,minY:box.min.y,maxY:box.max.y,musicPaused:c.audio.music.paused,musicVolume:c.audio.music.volume,chest:c.renderer.chest.visible,data:first};}finally{ctx.fillText=original;}})()`);
 assert.equal(row.stage,stage);assert.ok(row.restored&&row.stable);assert.ok(row.visible);assert.ok(!row.chest);assert.ok(!row.texts.some(t=>t.includes('prévia')||t.includes('Urso a')||t.includes('%')));
 if(stage==='GAME_OVER'){assert.ok(row.rotation< -1.4);assert.ok(row.minY>-.15&&row.maxY<1,'Queda deve permanecer junto do solo: '+JSON.stringify(row));assert.ok(row.musicPaused);assert.equal(row.musicVolume,0);assert.ok(row.texts.includes('Fim de jogo'));}
 const bytes=Buffer.from(row.data.split(',')[1],'base64'),file='/tmp/vidas-perseguicao-'+width+'-'+difficulty+'-'+stage+'.png';await fs.writeFile(file,bytes);captures.push({file,bytes:bytes.length,sha256:crypto.createHash('sha256').update(bytes).digest('hex')});delete row.data;rows.push({width,height,...row});
 }
 }
 assert.deepEqual(exceptions,[]);assert.deepEqual(failed,[]);
 console.log('APROVADO: 18 cenas, duas dificuldades, HUD sem textos anteriores, perda de vidas, queda visível, fim de jogo, áudio parado e save/pausa estáveis.',JSON.stringify({rows,captures}));
}finally{ws.close();await fetch('http://127.0.0.1:9222/json/close/'+page.id);}
